interface TableSchema {
  name: string;
  columns: ColumnInfo[];
  indexes: IndexInfo[];
}

interface ColumnInfo {
  name: string;
  type: string;
  nullable: boolean;
  default?: string;
  primary_key: boolean;
}

interface IndexInfo {
  name: string;
  columns: string[];
  unique: boolean;
}

export class SchemaComparator {
  private db: D1Database;

  constructor(db: D1Database) {
    this.db = db;
  }

  async getTableSchema(tableName: string): Promise<TableSchema | null> {
    // Get table info
    const tableInfo = await this.db.prepare(`
      SELECT name FROM sqlite_master 
      WHERE type='table' AND name=?
    `).bind(tableName).first();

    if (!tableInfo) return null;

    // Get column information
    const columns = await this.db.prepare(`
      PRAGMA table_info(${tableName})
    `).all();

    // Get index information
    const indexes = await this.db.prepare(`
      PRAGMA index_list(${tableName})
    `).all();

    const columnInfo: ColumnInfo[] = columns.results.map((col: any) => ({
      name: col.name,
      type: col.type,
      nullable: col.notnull === 0,
      default: col.dflt_value,
      primary_key: col.pk > 0
    }));

    const indexInfo: IndexInfo[] = indexes.results.map((idx: any) => ({
      name: idx.name,
      columns: [], // Would need additional query to get columns
      unique: idx.unique === 1
    }));

    return {
      name: tableName,
      columns: columnInfo,
      indexes: indexInfo
    };
  }

  async compareTables(expected: string[], actual: string[]): Promise<{
    missing: string[];
    extra: string[];
    matching: string[];
  }> {
    const missing = expected.filter(table => !actual.includes(table));
    const extra = actual.filter(table => !expected.includes(table));
    const matching = expected.filter(table => actual.includes(table));

    return { missing, extra, matching };
  }

  async needsTableRecreation(tableName: string, expectedSQL: string): Promise<boolean> {
    const currentSchema = await this.getTableSchema(tableName);
    
    if (!currentSchema) return true;

    // For simplicity, we'll use checksum comparison
    // In production, you'd want more sophisticated schema diffing
    const currentChecksum = await this.generateSchemaChecksum(tableName);
    const expectedChecksum = await this.generateChecksum(expectedSQL);

    return currentChecksum !== expectedChecksum;
  }

  private async generateSchemaChecksum(tableName: string): Promise<string> {
    const schema = await this.getTableSchema(tableName);
    if (!schema) return '';

    const schemaString = JSON.stringify(schema);
    return this.simpleHash(schemaString);
  }

  private async generateChecksum(sql: string): Promise<string> {
    return this.simpleHash(sql);
  }

  private simpleHash(str: string): string {
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
      const char = str.charCodeAt(i);
      hash = ((hash << 5) - hash) + char;
      hash = hash & hash; // Convert to 32-bit integer
    }
    return hash.toString(16);
  }

  async dropTable(tableName: string): Promise<void> {
    await this.db.prepare(`DROP TABLE IF EXISTS ${tableName}`).run();
  }

  async createTable(sql: string): Promise<void> {
    await this.db.exec(sql);
  }
}
