import { MigrationService } from './shared/infrastructure/database/migrations/migration.service';
import { UserRoutes, RouteHandler } from './modules/users/routes/user.routes';

interface Env {
  DB: D1Database;
  JWT_SECRET: string;
}

export async function createApp(env: Env): Promise<(request: Request) => Promise<Response>> {
  // Initialize database migrations
  console.log('🚀 Initializing FreeEducation Backend...');
  
  const migrationService = new MigrationService(env.DB);
  await migrationService.initialize();
  await migrationService.runMigrations();
  
  // Initialize routes
  const userRoutes = new UserRoutes(env.DB);
  const allRoutes: RouteHandler[] = [
    ...userRoutes.getRoutes(),
  ];

  // Simple path matching function
  function matchRoute(path: string, method: string): { handler: RouteHandler['handler']; params: any } | null {
    for (const route of allRoutes) {
      if (route.method === method) {
        // Simple parameter matching for /api/v1/users/:id
        if (route.path.includes(':id')) {
          const routeParts = route.path.split('/');
          const pathParts = path.split('/');
          
          if (routeParts.length === pathParts.length) {
            let matches = true;
            const params: any = {};
            
            for (let i = 0; i < routeParts.length; i++) {
              if (routeParts[i].startsWith(':')) {
                const paramName = routeParts[i].substring(1);
                params[paramName] = pathParts[i];
              } else if (routeParts[i] !== pathParts[i]) {
                matches = false;
                break;
              }
            }
            
            if (matches) {
              return { handler: route.handler, params };
            }
          }
        } else if (route.path === path) {
          return { handler: route.handler, params: {} };
        }
      }
    }
    return null;
  }

  // Main request handler
  return async (request: Request): Promise<Response> => {
    const url = new URL(request.url);
    const path = url.pathname;
    const method = request.method;

    // Add CORS headers
    const corsHeaders = {
      'Access-Control-Allow-Origin': '*',
      'Access-Control-Allow-Methods': 'GET, POST, PUT, DELETE, OPTIONS',
      'Access-Control-Allow-Headers': 'Content-Type, Authorization',
    };

    // Handle preflight requests
    if (method === 'OPTIONS') {
      return new Response(null, { headers: corsHeaders });
    }

    // Route matching
    const match = matchRoute(path, method);
    if (match) {
      try {
        const response = await match.handler(request, match.params, env);
        
        // Add CORS headers to response
        Object.entries(corsHeaders).forEach(([key, value]) => {
          response.headers.set(key, value);
        });
        
        return response;
      } catch (error) {
        console.error('Route handler error:', error);
        return new Response(JSON.stringify({
          success: false,
          error: 'Internal server error'
        }), {
          status: 500,
          headers: { 
            'Content-Type': 'application/json',
            ...corsHeaders
          }
        });
      }
    }

    // 404 - No route matched
    return new Response(JSON.stringify({
      success: false,
      error: 'Route not found',
      message: `Cannot ${method} ${path}`
    }), {
      status: 404,
      headers: { 
        'Content-Type': 'application/json',
        ...corsHeaders
      }
    });
  };
}