import { UserEntity } from '../entities/user.entity';
import { CreateUserRequest, UpdateUserRequest } from '../../../shared/types/user.types';

export class UserRepository {
  private db: D1Database;

  constructor(db: D1Database) {
    this.db = db;
  }

  async create(userData: CreateUserRequest): Promise<UserEntity> {
    const hashedPassword = await this.hashPassword(userData.password);
    
    const result = await this.db.prepare(`
      INSERT INTO users (email, password_hash, role, first_name, last_name, avatar_url, bio)
      VALUES (?, ?, ?, ?, ?, ?, ?)
    `).bind(
      userData.email,
      hashedPassword,
      userData.role,
      userData.first_name,
      userData.last_name,
      userData.avatar_url || null,
      userData.bio || null
    ).run();

    if (!result.success) {
      throw new Error('Failed to create user');
    }

    const user = await this.findById(result.meta.last_row_id!);
    if (!user) {
      throw new Error('User created but not found');
    }

    return user;
  }

  async findById(id: number): Promise<UserEntity | null> {
    const result = await this.db.prepare(`
      SELECT * FROM users WHERE id = ? AND is_active = 1
    `).bind(id).first();

    return result ? UserEntity.fromDatabaseRow(result) : null;
  }

  async findByEmail(email: string): Promise<UserEntity | null> {
    const result = await this.db.prepare(`
      SELECT * FROM users WHERE email = ? AND is_active = 1
    `).bind(email).first();

    return result ? UserEntity.fromDatabaseRow(result) : null;
  }

  async findByEmailWithPassword(email: string): Promise<UserEntity | null> {
    const result = await this.db.prepare(`
      SELECT * FROM users WHERE email = ? AND is_active = 1
    `).bind(email).first();

    return result ? UserEntity.fromDatabaseRow(result) : null;
  }

  async update(id: number, updateData: UpdateUserRequest): Promise<UserEntity | null> {
    const fields = [];
    const values = [];

    if (updateData.first_name !== undefined) {
      fields.push('first_name = ?');
      values.push(updateData.first_name);
    }
    if (updateData.last_name !== undefined) {
      fields.push('last_name = ?');
      values.push(updateData.last_name);
    }
    if (updateData.avatar_url !== undefined) {
      fields.push('avatar_url = ?');
      values.push(updateData.avatar_url);
    }
    if (updateData.bio !== undefined) {
      fields.push('bio = ?');
      values.push(updateData.bio);
    }
    if (updateData.is_active !== undefined) {
      fields.push('is_active = ?');
      values.push(updateData.is_active ? 1 : 0);
    }

    if (fields.length === 0) {
      return await this.findById(id);
    }

    fields.push('updated_at = CURRENT_TIMESTAMP');
    values.push(id);

    const result = await this.db.prepare(`
      UPDATE users SET ${fields.join(', ')} WHERE id = ?
    `).bind(...values).run();

    if (!result.success) {
      throw new Error('Failed to update user');
    }

    return await this.findById(id);
  }

  async delete(id: number): Promise<boolean> {
    const result = await this.db.prepare(`
      UPDATE users SET is_active = 0, updated_at = CURRENT_TIMESTAMP WHERE id = ?
    `).bind(id).run();

    return result.success && (result.meta.changes || 0) > 0;
  }

  async findAll(limit: number = 50, offset: number = 0): Promise<UserEntity[]> {
    const result = await this.db.prepare(`
      SELECT * FROM users WHERE is_active = 1 
      ORDER BY created_at DESC 
      LIMIT ? OFFSET ?
    `).bind(limit, offset).all();

    return result.results.map((row: any) => UserEntity.fromDatabaseRow(row));
  }

  async count(): Promise<number> {
    const result = await this.db.prepare(`
      SELECT COUNT(*) as count FROM users WHERE is_active = 1
    `).first();

    return result?.count || 0;
  }

  private async hashPassword(password: string): Promise<string> {
    // Simple hash for now - will be replaced with proper bcrypt
    return password; // TODO: Implement proper password hashing with bcrypt
  }
}
