import { SCHEMA_REGISTRY, LATEST_VERSION, SchemaVersion } from '../schemas/registry';

export interface MigrationRecord {
  version: string;
  applied_at: string;
  checksum: string;
}

export class VersionManager {
  private db: D1Database;

  constructor(db: D1Database) {
    this.db = db;
  }

  async initializeMigrationTable(): Promise<void> {
    await this.db.exec(`
      CREATE TABLE IF NOT EXISTS schema_migrations (
        version TEXT PRIMARY KEY,
        applied_at DATETIME DEFAULT CURRENT_TIMESTAMP,
        checksum TEXT NOT NULL
      )
    `);
  }

  async getCurrentVersion(): Promise<string | null> {
    const result = await this.db.prepare(
      'SELECT version FROM schema_migrations ORDER BY applied_at DESC LIMIT 1'
    ).first();
    
    return result?.version || null;
  }

  async getAppliedMigrations(): Promise<MigrationRecord[]> {
    const result = await this.db.prepare(
      'SELECT * FROM schema_migrations ORDER BY applied_at ASC'
    ).all();
    
    return result.results as MigrationRecord[];
  }

  async markMigrationApplied(version: string, checksum: string): Promise<void> {
    await this.db.prepare(
      'INSERT OR REPLACE INTO schema_migrations (version, checksum) VALUES (?, ?)'
    ).bind(version, checksum).run();
  }

  async needsUpgrade(): Promise<boolean> {
    const currentVersion = await this.getCurrentVersion();
    return currentVersion !== LATEST_VERSION;
  }

  getPendingMigrations(currentVersion: string | null): string[] {
    if (!currentVersion) {
      return Object.keys(SCHEMA_REGISTRY);
    }

    const versions = Object.keys(SCHEMA_REGISTRY);
    const currentIndex = versions.indexOf(currentVersion);
    
    if (currentIndex === -1) {
      return versions; // Fresh start
    }

    return versions.slice(currentIndex + 1);
  }

  getSchemaVersion(version: SchemaVersion) {
    return SCHEMA_REGISTRY[version];
  }
}
