import { UserService } from '../services/user.service';
import { CreateUserRequest, UpdateUserRequest } from '../../../shared/types/user.types';

export class UserController {
  private userService: UserService;

  constructor(db: D1Database) {
    this.userService = new UserService(db);
  }

  async createUser(request: Request): Promise<Response> {
    try {
      const body = await request.json() as CreateUserRequest;
      const user = await this.userService.createUser(body);
      
      return new Response(JSON.stringify({
        success: true,
        data: user,
        message: 'User created successfully'
      }), {
        status: 201,
        headers: { 'Content-Type': 'application/json' }
      });
    } catch (error) {
      return this.handleError(error);
    }
  }

  async getUserById(request: Request, params: { id: string }): Promise<Response> {
    try {
      const id = parseInt(params.id);
      if (isNaN(id)) {
        return new Response(JSON.stringify({
          success: false,
          error: 'Invalid user ID'
        }), {
          status: 400,
          headers: { 'Content-Type': 'application/json' }
        });
      }

      const user = await this.userService.getUserById(id);
      if (!user) {
        return new Response(JSON.stringify({
          success: false,
          error: 'User not found'
        }), {
          status: 404,
          headers: { 'Content-Type': 'application/json' }
        });
      }

      return new Response(JSON.stringify({
        success: true,
        data: user
      }), {
        headers: { 'Content-Type': 'application/json' }
      });
    } catch (error) {
      return this.handleError(error);
    }
  }

  async updateUser(request: Request, params: { id: string }): Promise<Response> {
    try {
      const id = parseInt(params.id);
      if (isNaN(id)) {
        return new Response(JSON.stringify({
          success: false,
          error: 'Invalid user ID'
        }), {
          status: 400,
          headers: { 'Content-Type': 'application/json' }
        });
      }

      const body = await request.json() as UpdateUserRequest;
      const user = await this.userService.updateUser(id, body);
      
      if (!user) {
        return new Response(JSON.stringify({
          success: false,
          error: 'User not found'
        }), {
          status: 404,
          headers: { 'Content-Type': 'application/json' }
        });
      }

      return new Response(JSON.stringify({
        success: true,
        data: user,
        message: 'User updated successfully'
      }), {
        headers: { 'Content-Type': 'application/json' }
      });
    } catch (error) {
      return this.handleError(error);
    }
  }

  async deleteUser(request: Request, params: { id: string }): Promise<Response> {
    try {
      const id = parseInt(params.id);
      if (isNaN(id)) {
        return new Response(JSON.stringify({
          success: false,
          error: 'Invalid user ID'
        }), {
          status: 400,
          headers: { 'Content-Type': 'application/json' }
        });
      }

      const success = await this.userService.deleteUser(id);
      
      if (!success) {
        return new Response(JSON.stringify({
          success: false,
          error: 'User not found'
        }), {
          status: 404,
          headers: { 'Content-Type': 'application/json' }
        });
      }

      return new Response(JSON.stringify({
        success: true,
        message: 'User deleted successfully'
      }), {
        headers: { 'Content-Type': 'application/json' }
      });
    } catch (error) {
      return this.handleError(error);
    }
  }

  async getAllUsers(request: Request): Promise<Response> {
    try {
      const url = new URL(request.url);
      const limit = parseInt(url.searchParams.get('limit') || '50');
      const offset = parseInt(url.searchParams.get('offset') || '0');

      const users = await this.userService.getAllUsers(limit, offset);
      const count = await this.userService.getUserCount();

      return new Response(JSON.stringify({
        success: true,
        data: users,
        pagination: {
          limit,
          offset,
          total: count,
          hasMore: offset + limit < count
        }
      }), {
        headers: { 'Content-Type': 'application/json' }
      });
    } catch (error) {
      return this.handleError(error);
    }
  }

  private handleError(error: any): Response {
    console.error('UserController error:', error);
    
    const message = error instanceof Error ? error.message : 'Internal server error';
    const status = message.includes('not found') ? 404 : 
                   message.includes('already exists') ? 409 : 500;

    return new Response(JSON.stringify({
      success: false,
      error: message
    }), {
      status,
      headers: { 'Content-Type': 'application/json' }
    });
  }
}
