import { UserRepository } from '../repositories/user.repo';
import { UserEntity } from '../entities/user.entity';
import { CreateUserRequest, UpdateUserRequest, UserResponse } from '../../../shared/types/user.types';

export class UserService {
  private userRepository: UserRepository;

  constructor(db: D1Database) {
    this.userRepository = new UserRepository(db);
  }

  async createUser(userData: CreateUserRequest): Promise<UserResponse> {
    // Check if user already exists
    const existingUser = await this.userRepository.findByEmail(userData.email);
    if (existingUser) {
      throw new Error('User with this email already exists');
    }

    const user = await this.userRepository.create(userData);
    return user.toJSON();
  }

  async getUserById(id: number): Promise<UserResponse | null> {
    const user = await this.userRepository.findById(id);
    return user ? user.toJSON() : null;
  }

  async getUserByEmail(email: string): Promise<UserResponse | null> {
    const user = await this.userRepository.findByEmail(email);
    return user ? user.toJSON() : null;
  }

  async updateUser(id: number, updateData: UpdateUserRequest): Promise<UserResponse | null> {
    const user = await this.userRepository.update(id, updateData);
    return user ? user.toJSON() : null;
  }

  async deleteUser(id: number): Promise<boolean> {
    return await this.userRepository.delete(id);
  }

  async getAllUsers(limit: number = 50, offset: number = 0): Promise<UserResponse[]> {
    const users = await this.userRepository.findAll(limit, offset);
    return users.map(user => user.toJSON());
  }

  async getUserCount(): Promise<number> {
    return await this.userRepository.count();
  }

  async searchUsers(query: string, limit: number = 20): Promise<UserResponse[]> {
    // This would require implementing a search method in the repository
    // For now, return all users
    const users = await this.userRepository.findAll(limit, 0);
    return users.map(user => user.toJSON());
  }
}
